UPDATE pages SET excerpt = 'Soutiens-gorge variés, avec ou sans armature, et petites culottes assorties, pour toutes les tailles.', hero_image = '/uploads/bibliotheque/rosemary-1.png', body = '<p>Lingerie féminine pour toutes les tailles : soutiens-gorge variés, avec ou sans armature, et petites culottes assorties.</p>
<h2>Des marques reconnues</h2>
<p>Anita, Rosa Faia, Montelle, Van de Velde, PrimaDonna, Marie Jo et Fit Fully Yours.</p>
<h2>La bonne taille</h2>
<p>Nous prenons vos mesures dans le respect et la plus grande discrétion, ce qui vous assure un bon maintien et le plus grand confort. Nos cabines sont grandes et spacieuses.</p>
<p>À lire sur le blogue : <a href="/blog/a-chaque-soutien-gorge-sa-circonstance">À chaque soutien-gorge sa circonstance</a> et <a href="/blog/avez-vous-assez-de-soutien-gorge">Avez-vous assez de soutien-gorge?</a></p>', status = 'published', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE slug = 'soutien-gorge-tailles-variees-lingeriechristine' AND nav_section = 'produits';
UPDATE pages SET excerpt = 'Maillots de bain pour tous les types de tailles, aux tendances actuelles, confortables et adaptés aux poitrines épanouies.', hero_image = '/uploads/bibliotheque/maillot-2026-2.png', body = '<p>Maillots de bain pour tous les types de tailles aux tendances mode actuelles, aussi confortables qu’adaptés aux poitrines épanouies, dont les maillots PrimaDonna.</p>
<p>Comme pour un soutien-gorge, on prend vos mesures et on vous conseille le maillot ajusté à votre morphologie.</p>', status = 'published', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE slug = 'maillots-de-bain-lingeriechristine' AND nav_section = 'produits';
UPDATE pages SET excerpt = 'Service-conseil professionnel en vêtements postopératoires et prothèses mammaires, par une équipe formée et certifiée par Anita.', hero_image = '/uploads/blog/594/fr/lingerie-christine-post-mastectomie-.png', body = '<p>Nous offrons un service-conseil professionnel en vêtements postopératoires : l’équipe est dûment formée et certifiée par la marque Anita, reconnue pour son expertise dans ce domaine.</p>
<p>Notre priorité est que chaque femme se sente belle et confiante, malgré les défis physiques et émotionnels.</p>
<p>À lire sur le blogue : <a href="/blog/soutien-gorge-postmastectomie-une-solution-pour-retrouver-sa-vie-de-femme">Soutien-gorge postmastectomie : une solution pour retrouver sa vie de femme</a> et <a href="/blog/modele-anita-elegance-et-confort-certifie-oeko-tex">Modèle Anita : élégance et confort certifié OEKO-TEX®</a></p>', status = 'published', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE slug = 'protheses-mammaires-et-sous-vetements-post-operatoire' AND nav_section = 'produits';
UPDATE pages SET excerpt = 'Des nuisettes confortables de la marque Montelle, au confort inégalé, et des peignoirs tout doux.', hero_image = '/uploads/blog/598/fr/croppedImg_1447510414.png', body = '<p>Des nuisettes confortables de la marque Montelle, au confort inégalé, et des peignoirs pour des soirées tout en douceur.</p>
<p>À lire sur le blogue : <a href="/blog/une-nuit-de-reve-dans-un-vetement-tout-doux-">Une nuit de rêve dans un vêtement tout doux</a></p>', status = 'published', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE slug = 'nuisette-peignoir-et-compagnie-lingeriechristine' AND nav_section = 'produits';
UPDATE pages SET excerpt = 'Lingerie et vêtements de sport ajustés à votre morphologie et à votre activité.', hero_image = '', body = '<p>Que vous cherchiez de la lingerie de sport ou de tous les jours, notre équipe vous aide à trouver un modèle ajusté à votre morphologie et à votre activité.</p>', status = 'published', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE slug = 'vetements-sport-lingeriechristine-' AND nav_section = 'produits';
